"use client";

import * as motion from "motion/react-client";
import Link from "next/link";
import { useState,memo } from "react";
import Container from "../components/container";
import MobileMenu from "./mobile-menu";
import { ArrowRight, Menu, X } from "lucide-react";
import { AnimatePresence } from "motion/react";
import Image from "next/image";
import { navlink as quicklink } from "../lib/data/navlink";

function Navbar() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <nav className="py-4 z-50 sticky top-0 shadow-md backdrop-blur-sm bg-black/50">
      <Container className="px-4">
        <div className="flex justify-between ">
          <motion.div whileTap={{ scale: 1.05 }} className="cursor-pointer">
            <Link href="/" aria-label="Home">

              <Image
              src="/portfolio/logo.svg"
                width={50}
                height={25}
                alt="logo"
                loading="eager"
                className="hover:opacity-80 transition-opacity h-6 md:h-8 w-auto"
              />
            </Link>
          </motion.div>

          <NavLinks />

          <motion.a
            href="mailto:contact@rajeevpuri.com.np"
            className="hidden md:flex items-center hover:text-blue-500 hover:underline font-semibold transition-all "
          >
            contact@rajeevpuri.com.np

          </motion.a>

          <motion.button
            whileTap={{ scale: 0.95 }}
            onClick={() => setIsOpen(!isOpen)}
            className="md:hidden text-white"
            aria-label="Toggle menu"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </motion.button>
        </div>
      </Container>

      <AnimatePresence mode="wait">
        {isOpen && <MobileMenu onClose={() => setIsOpen(false)} />}
      </AnimatePresence>
    </nav>
  );
}

const NavLinks = memo(function NavLinks() {
  return (
    <div className="hidden md:flex space-x-6 lg:space-x-8">
      {quicklink.map((link) => (
        <motion.a
          key={link.id}
          href={link.url}
          className="flex items-center hover:text-blue-500 text-sm lg:text-base font-semibold transition-colors"
          whileTap={{ scale: 1.1 }}
        >
          {link.title}
        </motion.a>
      ))}
    </div>
  );
});

export default memo(Navbar);

"use client";

import * as motion from "motion/react-client";
import { ArrowRight } from "lucide-react";
import { navlink as quicklink } from "../lib/data/navlink";

interface MobileMenuProps {
  onClose: () => void;
}

export default function MobileMenu({ onClose }: MobileMenuProps) {
  return (
    <motion.div
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: "auto" }}
      exit={{ opacity: 0, height: 0 }}
      transition={{ duration: 0.3, ease: "easeInOut" }}
      className="md:hidden absolute top-full left-0 w-full bg-[#030303]/95 backdrop-blur-xl border-t border-white/10 overflow-hidden shadow-2xl"
    >
      <div className="flex flex-col space-y-4 p-6">
        {quicklink.map((link) => (
          <motion.a
            key={link.id}
            href={link.url}
            className="flex items-center text-lg font-medium text-zinc-400 hover:text-white transition-colors"
            whileTap={{ scale: 0.98 }}
            onClick={onClose}
          >
            {link.title}
          </motion.a>
        ))}
        <motion.a
          href="mailto:contact@rajeevpuri.com.np"
          className="flex items-center pt-4"
          onClick={onClose}
        >
          <button className="w-full bg-white text-black px-6 py-4 rounded-full text-sm font-bold flex items-center justify-center gap-2 hover:bg-zinc-200 transition-all active:scale-95">
            Lets Talk <ArrowRight size={16} />
          </button>
        </motion.a>
      </div>
    </motion.div>
  );
}

import { cn } from '../lib/utils'

import * as motion from "motion/react-client";
import { ReactNode } from "react";

interface ContainerProps {
  id?: string;
  children: ReactNode;
  className?: string;
  variants?: any;
  initial?: any;
  animate?: any;
  transition?: any;
}

export default function Container({
  id,
  children,
  className,
  variants,
  initial = "hidden",
  animate = "visible",
  transition,
}: Readonly<ContainerProps>) {
  return (
    <motion.section
      id={id}
      className={cn(className, "max-w-6xl mx-auto overflow-x-hidden")}
      variants={variants}
      initial={initial}
      animate={animate}
      transition={transition}
    >
      {children}
    </motion.section>
  );
}

interface QuickLink {
  id: string;
  title: string;
  url: string;
}
export const navlink: QuickLink[] = [
  {
    id: "projects",
    title: "Projects",
    url: "/projects",
  },

  {
    id: "about",
    title: "About",
    url: "/about",
  },
  {
    id: "contact",
    title: "Contact",
    url: "/contact",
  },
  {
    id: "blog",
    title: "Blog",
    url: "/blog",
  },
];

export { cn } from "cn"

export const currentYear = new Date().getFullYear().toString();
export function formatDate(date: string | Date): string {
  const dateObj = typeof date === "string" ? new Date(date) : date
  return new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(dateObj)
}

@theme inline {
  --color-primary-light: var(--primary);
  --color-primary-hover: var(--primary);
  --color-accent-cyan: var(--secondary);
  --color-accent-purple: var(--primary);
  --color-info: var(--primary);
  --shadow-glow: 0 0 20px color-mix(in oklab, var(--primary) 15%, transparent);
  --shadow-glow-lg: 0 0 30px color-mix(in oklab, var(--primary) 25%, transparent);
  --font-heading: var(--font-sans);
}

@layer components {
  /* Example utility combining the new theme variables */
  .btn-primary-glow {
    @apply bg-primary text-primary-foreground shadow-glow hover:shadow-glow-lg
           transition-all duration-200 active:scale-95;
  }

  .blog-content > table,
  .blog-content > .table-wrapper > table {
    width: 100%;
    margin: 2rem 0;
    border-collapse: separate;
    border-spacing: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    background: color-mix(in oklab, var(--background) 60%, transparent);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.08);
    font-size: 0.95rem;
  }

  .blog-content > table[header-row="true"] tbody tr:first-child td,
  .blog-content > table thead th,
  .blog-content > .table-wrapper > table[header-row="true"] tbody tr:first-child td,
  .blog-content > .table-wrapper > table thead th {
    background: color-mix(in oklab, var(--muted) 40%, transparent);
    color: var(--foreground);
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }

  .blog-content > table td,
  .blog-content > table th,
  .blog-content > .table-wrapper > table td,
  .blog-content > .table-wrapper > table th {
    padding: 0.9rem 1rem;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: top;
    color: var(--muted-foreground);
  }

  .blog-content > table tr:last-child td,
  .blog-content > table tr:last-child th,
  .blog-content > .table-wrapper > table tr:last-child td,
  .blog-content > .table-wrapper > table tr:last-child th {
    border-bottom: 0;
  }

  .blog-content > table td code,
  .blog-content > table th code,
  .blog-content > .table-wrapper > table td code,
  .blog-content > .table-wrapper > table th code {
    display: inline-block;
    padding: 0.1rem 0.35rem;
    border-radius: calc(var(--radius) * 0.45);
    background: var(--muted);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 0.85em;
    font-weight: 600;
  }


}
